<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, unwrapPage } from './services/api'

type LibraryRow = { id: string; title: string; type: string; lifecycle: string; owner: string; updated: string; favorite: boolean }
const actorId = String(import.meta.env.VITE_ACTOR_ID || ''); const query = ref(''); const typeFilter = ref('全部'); const lifecycleFilter = ref('全部'); const loading = ref(false); const dialog = ref(false); const title = ref(''); const resourceType = ref('电影'); const toast = ref('')
const rows = ref<LibraryRow[]>([{ id: 'demo-resource', title: '《星际穿越》', type: '电影', lifecycle: '正常', owner: '陈昊', updated: '12 分钟前', favorite: true }, { id: 'demo-document', title: 'Ikaros V2 产品设计', type: '文档', lifecycle: '正常', owner: '陈昊', updated: '昨天', favorite: false }, { id: 'demo-archived', title: '旧项目资料', type: '集合', lifecycle: '已归档', owner: '陈昊', updated: '5 天前', favorite: false }])
const types = ['全部', '电影', '文档', '集合', '音乐', '文章']; const lifecycles = ['全部', '正常', '已归档', '回收站']
const filteredRows = computed(() => rows.value.filter(row => (!query.value || `${row.title} ${row.type} ${row.owner}`.toLowerCase().includes(query.value.toLowerCase())) && (typeFilter.value === '全部' || row.type === typeFilter.value) && (lifecycleFilter.value === '全部' || row.lifecycle === lifecycleFilter.value)))
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
async function load() { loading.value = true; try { const result = unwrapPage(await api.listResources('?limit=50')); if (result.length) rows.value = result.map(item => ({ id: item.id, title: item.title || item.id.slice(0, 8), type: item.resource_type || '其他', lifecycle: item.lifecycle || '正常', owner: '当前用户', updated: item.updated_at ? new Date(item.updated_at).toLocaleString('zh-CN') : '刚刚', favorite: false })) } catch { if (!import.meta.env.DEV) notify('资源库加载失败') } finally { loading.value = false } }
async function create() { if (!title.value.trim()) { notify('请输入资源标题'); return } try { if (actorId) { const item = await api.createResource({ title: title.value.trim(), resource_type: resourceType.value, owner_id: actorId }); rows.value.unshift({ id: item.id, title: item.title || title.value.trim(), type: item.resource_type || resourceType.value, lifecycle: item.lifecycle || '正常', owner: '当前用户', updated: '刚刚', favorite: false }) } else { rows.value.unshift({ id: `demo-${Date.now()}`, title: title.value.trim(), type: resourceType.value, lifecycle: '正常', owner: '当前用户', updated: '刚刚', favorite: false }) } dialog.value = false; title.value = ''; notify('资源已创建') } catch (error) { notify(error instanceof Error ? error.message : '资源创建失败') } }
function toggleFavorite(row: LibraryRow) { row.favorite = !row.favorite; notify(row.favorite ? '已加入收藏' : '已取消收藏') }
onMounted(load)
</script>

<template><div class="library-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">内容与创作 · 本地环境</span><span class="mini-avatar">陈</span></header><main class="library-main"><div class="catalog-heading"><div><p class="eyebrow">内容与创作</p><h1>统一资源库</h1><p>Resource 表示逻辑内容，而不是物理存储位置。</p></div><div class="library-actions"><button class="outlined-button" @click="notify('导入流程即将打开')">⇩ 导入</button><button class="filled-button" @click="dialog = true">＋ 创建资源</button></div></div><div class="library-kpis"><div class="mini-kpi"><span>资源总数</span><b>{{ rows.length }}</b><small>当前授权范围</small></div><div class="mini-kpi"><span>正常可用</span><b class="success-text">{{ rows.filter(row => row.lifecycle === '正常').length }}</b><small>可正常使用</small></div><div class="mini-kpi"><span>已归档</span><b>{{ rows.filter(row => row.lifecycle === '已归档').length }}</b><small>仍可恢复</small></div><div class="mini-kpi"><span>元数据冲突</span><b class="warning-text">0</b><small>需要关注</small></div></div><section class="library-toolbar surface-card"><div class="search-inline"><span>⌕</span><input v-model="query" placeholder="搜索资源标题、别名或 ID" /></div><div class="filter-row"><button v-for="value in types" :key="value" class="filter-chip" :class="{ active: typeFilter === value }" @click="typeFilter = value">{{ value }}</button></div><select v-model="lifecycleFilter"><option v-for="value in lifecycles" :key="value">{{ value }}</option></select></section><section class="library-table surface-card"><table><thead><tr><th>资源</th><th>类型</th><th>生命周期</th><th>所有者</th><th>最近更新</th><th>收藏</th><th>操作</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id"><td><RouterLink :to="`/console/resources/${row.id}`" class="library-name"><span class="row-icon">◈</span><b>{{ row.title }}</b></RouterLink></td><td><span class="status-chip neutral">{{ row.type }}</span></td><td><span class="status-chip" :class="row.lifecycle === '正常' ? 'success' : 'warning'">● {{ row.lifecycle }}</span></td><td>{{ row.owner }}</td><td class="muted-text">{{ row.updated }}</td><td><button class="favorite-button" :class="{ active: row.favorite }" @click="toggleFavorite(row)">{{ row.favorite ? '★' : '☆' }}</button></td><td><RouterLink :to="`/console/resources/${row.id}`" class="text-button">查看 →</RouterLink></td></tr><tr v-if="filteredRows.length === 0"><td colspan="7" class="no-results">没有匹配资源，请调整筛选条件。</td></tr></tbody></table><div class="table-footer"><span>显示 {{ filteredRows.length }} 项，共 {{ rows.length }} 项</span><button class="text-button" :disabled="loading" @click="load">{{ loading ? '加载中…' : '⟳ 刷新' }}</button></div></section></main><div v-if="dialog" class="role-create-scrim" @click.self="dialog = false"><section class="role-create-dialog"><div class="dialog-title"><div><p class="eyebrow">内容与创作</p><h2>创建资源</h2></div><button class="icon-button" @click="dialog = false">×</button></div><label>标题<input v-model="title" placeholder="输入资源标题" /></label><label>类型<select v-model="resourceType"><option v-for="value in types.slice(1)" :key="value">{{ value }}</option></select></label><p class="account-note">创建后 Resource 类型默认不可直接修改；后续可在详情页添加附件与外部身份。</p><div class="dialog-actions"><button class="outlined-button" @click="dialog = false">取消</button><button class="filled-button" @click="create">创建资源</button></div></section></div><div v-if="toast" class="snackbar">✓ {{ toast }}<button @click="toast = ''">×</button></div></div></template>
